#!/usr/bin/env node
/**
 * Production spectral (V2 score-informed) corpus benchmark — the A/B
 * counterpart of scripts/score-neural-notes.mjs.
 *
 * Replays every corpus clip through the SAME production modules the live
 * Wait For You path uses:
 *   processMicEngineV2Tick  (v2/micEngineV2Live.js)
 *   evaluateMicScoreInformedInput / evaluateMicMatch (waitForYouNoteMatch.js)
 *   micMatchConfirm / micAttackLatch / micMusicalAcceptance
 * so the numbers describe the shipped recognizer, not a re-implementation.
 *
 * Scenarios are generated by the shared generator so the spectral and
 * neural scores are directly comparable.
 *
 * Usage:
 *   node scripts/benchmark-spectral-corpus.mjs --manifests mic-accuracy,mic-polyphony,mic-real,mic-composites \
 *     [--split dev] [--json /tmp/spectral.json]
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { readWavPcm } from './lib/readWavPcm.mjs'
import { wrongExpectations } from './lib/micFalseAwardScenarios.mjs'
import { createMicFrameAnalyzer } from '../src/features/microphone-input/micFrameAnalysis.js'
import { getMicInstrumentProfile } from '../src/features/microphone-input/micInstrumentProfiles.js'
import {
  createMicEngineV2RuntimeState,
  processMicEngineV2Tick,
} from '../src/features/microphone-input/v2/micEngineV2Live.js'
import {
  confirmConfidentMatch,
  createMatchConfirmState,
  frameConfidentForMatch,
  frameCorroboratesSingleNote,
  resetMatchConfirmState,
} from '../src/features/practice/micMatchConfirm.js'
import {
  canAcceptMicAttackMatch,
  createMicAttackLatchState,
  getMicAttackRearmReason,
  markMicAttackConsumed,
  rearmMicAttackLatch,
  resetMicAttackLatch,
  updateMicAttackRelease,
} from '../src/features/practice/micAttackLatch.js'
import { isMusicalMicFrame } from '../src/features/practice/micMusicalAcceptance.js'
import { evaluateMicScoreInformedInput, MATCH_OUTCOME } from '../src/features/practice/waitForYouNoteMatch.js'
import { normalizeMatchSettings } from '../src/features/practice/waitForYouMatchSettings.js'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const SETTINGS = normalizeMatchSettings({})

function arg(name, fallback = null) {
  const prefix = `--${name}`
  for (let i = 2; i < process.argv.length; i += 1) {
    if (process.argv[i] === prefix) {
      return process.argv[i + 1] ?? fallback
    }
    if (process.argv[i].startsWith(`${prefix}=`)) {
      return process.argv[i].slice(prefix.length + 1)
    }
  }
  return fallback
}

const MANIFESTS = (arg('manifests', 'mic-accuracy,mic-polyphony,mic-real,mic-composites')).split(',')
const SPLIT = arg('split', null)
const JSON_OUT = arg('json', null)

const MANIFEST_SPECS = {
  // mic-accuracy: single expected note, optional start/end slicing.
  // truth: null — the neural corpus passes no truth list for the legacy
  // corpora, so every mutation scenario counts (identical denominators).
  'mic-accuracy': (clip) => ({
    file: clip.file,
    instrument: clip.instrument,
    expected: clip.expectedMidi != null ? [clip.expectedMidi] : (clip.expectedMidis ?? []),
    truth: null,
    startMs: clip.startMs,
    endMs: clip.endMs,
  }),
  // mic-polyphony: chord expectations, optional start/end slicing.
  'mic-polyphony': (clip) => ({
    file: clip.file,
    instrument: clip.instrument,
    expected: clip.expectedMidis ?? [],
    truth: null,
    startMs: clip.startMs,
    endMs: clip.endMs,
  }),
  // mic-real: anchor tones are the checkpoint; the full note list is truth.
  'mic-real': (clip) => ({
    file: clip.audio?.file,
    instrument: clip.instrument,
    expected: clip.truth?.anchorTones ?? [],
    truth: (clip.truth?.notes ?? []).map((note) => note.midi),
    split: clip.split,
  }),
  'mic-composites': (clip) => ({
    file: clip.audio?.file,
    instrument: clip.instrument,
    expected: clip.truth?.anchorTones ?? [],
    truth: (clip.truth?.notes ?? []).map((note) => note.midi),
  }),
}

function collectClips() {
  const clips = []
  for (const name of MANIFESTS) {
    const manifest = JSON.parse(readFileSync(join(ROOT, 'benchmarks', name, 'manifest.json'), 'utf8'))
    const spec = MANIFEST_SPECS[name]
    for (const clip of manifest.clips ?? []) {
      if (name === 'mic-real') {
        const excluded = new Set((manifest.excluded ?? []).map((entry) => entry.id))
        if (excluded.has(clip.id)) {
          continue
        }
        if (SPLIT && clip.split !== SPLIT) {
          continue
        }
      }
      const info = spec(clip)
      if (!info.file) {
        continue
      }
      clips.push({
        id: clip.id,
        corpus: name,
        instrument: info.instrument ?? 'piano',
        file: join(ROOT, 'benchmarks', name, info.file),
        expected: info.expected ?? [],
        truth: info.truth ?? [],
        startMs: info.startMs ?? null,
        endMs: info.endMs ?? null,
      })
    }
  }
  return clips
}

function hasStrongExpectedV2Evidence(frame, expectedMidi, { minConfidence = 0.48, minRatio = 2.2 } = {}) {
  return (frame?.v2Notes ?? []).some(
    (note) => note?.midi === expectedMidi && note.detected && (note.confidence ?? 0) >= minConfidence && (note.ratio ?? 0) >= minRatio,
  )
}

function frameConfidentForLiveMatch(frame, expectedMidi, attackRearmReason = null) {
  const scoreInformedSingleExpectedConfident =
    hasStrongExpectedV2Evidence(frame, expectedMidi) &&
    (frame.scoreInformedQuietGateOpen || attackRearmReason === 'score-informed-transition')
  return (frameConfidentForMatch(frame) || scoreInformedSingleExpectedConfident) && isMusicalMicFrame(frame)
}

/**
 * Replay one clip against one expectation set through the production
 * decision path. Returns { advanced, advanceTimeMs, heardMidis }.
 */
function replayExpectation(clip, samples, sampleRate, expectedMidis) {
  const profile = getMicInstrumentProfile(clip.instrument)
  const v2State = createMicEngineV2RuntimeState()
  const analyzer = createMicFrameAnalyzer()
  const confirm = createMatchConfirmState()
  const latch = createMicAttackLatchState()
  const fft = 2048
  const hop = Math.round(sampleRate / 60)
  const heard = new Set()
  let advanced = false
  let advanceTimeMs = null

  for (let end = fft; end <= samples.length; end += hop) {
    const timeMs = (end / sampleRate) * 1000
    const tick = processMicEngineV2Tick({
      buffer: new Float32Array(samples.subarray(end - fft, end)),
      sampleRate,
      expectedMidis,
      noiseFloor: analyzer.noiseFloor,
      state: v2State,
      centsTolerance: SETTINGS.micCentsTolerance,
      gateOptions: profile?.gate ?? null,
      timeMs,
    })
    const frame = tick.frame
    if (!frame) {
      continue
    }
    for (const midi of frame.v2DetectedMidis ?? []) {
      heard.add(midi)
    }
    updateMicAttackRelease(latch, Boolean(frame.gateOpen), { rms: frame.filteredRms ?? frame.rms ?? null })
    let attackRearmReason = null
    if (!canAcceptMicAttackMatch(latch)) {
      attackRearmReason = getMicAttackRearmReason(latch, frame, { expectedMidis })
      if (attackRearmReason) {
        rearmMicAttackLatch(latch)
      } else {
        resetMatchConfirmState(confirm)
        continue
      }
    }
    if (!frame.gateOpen || !frame.v2DetectedMidis?.length) {
      resetMatchConfirmState(confirm)
      continue
    }
    const preview = evaluateMicScoreInformedInput(
      { id: `bench-${clip.id}`, expectedMidi: expectedMidis[0] ?? null, expectedMidis },
      frame.v2DetectedMidis,
      SETTINGS,
    )
    if (preview.outcome !== MATCH_OUTCOME.COMPLETE) {
      resetMatchConfirmState(confirm)
      continue
    }
    // Production corroboration: single notes need pitch corroboration;
    // chords are corroborated by the multi-note detection itself.
    const corroborated =
      expectedMidis.length !== 1 ||
      frameCorroboratesSingleNote(frame, expectedMidis[0], { centsTolerance: SETTINGS.micCentsTolerance }) ||
      (attackRearmReason === 'score-informed-transition' && hasStrongExpectedV2Evidence(frame, expectedMidis[0]))
    const confident =
      corroborated &&
      (expectedMidis.length === 1
        ? frameConfidentForLiveMatch(frame, expectedMidis[0], attackRearmReason)
        : true)
    const key = `bench:${[...frame.v2DetectedMidis].sort((a, b) => a - b).join(',')}`
    if (confirmConfidentMatch(confirm, key, confident, { pitchCents: frame.midiFloat != null ? frame.midiFloat * 100 : null })) {
      resetMatchConfirmState(confirm)
      markMicAttackConsumed(latch, { consumedMidis: expectedMidis })
      advanced = true
      advanceTimeMs = timeMs
      break
    }
  }
  resetMicAttackLatch(latch)
  return { advanced, advanceTimeMs, heardMidis: [...heard] }
}

const clips = collectClips()
console.log(`spectral corpus benchmark: ${clips.length} clips (${MANIFESTS.join(', ')}${SPLIT ? ` split=${SPLIT}` : ''})`)

const results = []
for (const clip of clips) {
  let samples
  let sampleRate
  try {
    const wav = readWavPcm(clip.file)
    const raw = Float32Array.from(wav.samples)
    sampleRate = wav.sampleRate
    // Same slicing the production replay applies (micAccuracyManifest).
    const startSample = clip.startMs != null ? Math.floor((clip.startMs / 1000) * sampleRate) : 0
    const endSample = clip.endMs != null ? Math.floor((clip.endMs / 1000) * sampleRate) : raw.length
    samples = raw.subarray(Math.max(0, startSample), Math.max(startSample + 1, Math.min(endSample, raw.length)))
  } catch (error) {
    console.log(` ${clip.id}: SKIP (${error.message})`)
    continue
  }
  // truth === null means "no truth list" (legacy corpora): every mutation
  // scenario counts, exactly like the neural scorer on the same clips.
  const truth = clip.truth ?? null
  const trueResult = replayExpectation(clip, samples, sampleRate, clip.expected)
  const scenarios = wrongExpectations(clip.expected, truth)
  const falseCompletes = []
  for (const scenario of scenarios) {
    const result = replayExpectation(clip, samples, sampleRate, scenario.expected)
    if (result.advanced) {
      falseCompletes.push({ name: scenario.name, atMs: result.advanceTimeMs })
    }
  }
  // Silence/noise clips carry no expectation: they are not completion
  // scenarios (the neural corpus excludes them too) — they only must NOT
  // advance, which is asserted here.
  if (!clip.expected.length) {
    results.push({
      id: clip.id,
      corpus: clip.corpus,
      instrument: clip.instrument,
      expected: [],
      trueAdvanced: trueResult.advanced,
      trueAdvanceMs: trueResult.advanceTimeMs,
      heardMidis: trueResult.heardMidis,
      truth: [],
      scenarios: 0,
      falseCompletes: [],
      silenceClip: true,
    })
    console.log(` ${clip.id.padEnd(34)} silence-clip advanced=${trueResult.advanced} heard=[${trueResult.heardMidis.join(',')}]`)
    continue
  }
  results.push({
    id: clip.id,
    corpus: clip.corpus,
    instrument: clip.instrument,
    expected: clip.expected,
    trueAdvanced: trueResult.advanced,
    trueAdvanceMs: trueResult.advanceTimeMs,
    heardMidis: trueResult.heardMidis,
    truth,
    scenarios: scenarios.length,
    falseCompletes,
  })
  console.log(
    ` ${clip.id.padEnd(34)} true=${trueResult.advanced ? `ADV@${Math.round(trueResult.advanceTimeMs)}ms` : 'no'}`
    + ` fp=[${falseCompletes.map((entry) => entry.name).join(',') || '—'}]`
    + ` heard=[${trueResult.heardMidis.join(',')}]`,
  )
}

const trueComplete = results.filter((entry) => entry.trueAdvanced).length
const scoredClips = results.filter((entry) => !entry.silenceClip)
const scoredTrue = scoredClips.filter((entry) => entry.trueAdvanced).length
const scenarioTotal = results.reduce((sum, entry) => sum + entry.scenarios, 0)
const falseTotal = results.reduce((sum, entry) => sum + entry.falseCompletes.length, 0)
const silenceClips = results.filter((entry) => entry.silenceClip)
console.log('\n=== SPECTRAL (production v2 score-informed) ===')
console.log(JSON.stringify({
  clips: scoredClips.length,
  trueComplete: scoredTrue,
  trueCompleteRate: scoredClips.length ? scoredTrue / scoredClips.length : 0,
  falseCompletes: falseTotal,
  scenarios: scenarioTotal,
  silenceClips: silenceClips.length,
  silenceAdvanced: silenceClips.filter((entry) => entry.trueAdvanced).length,
}, null, 1))

if (JSON_OUT) {
  writeFileSync(JSON_OUT, JSON.stringify({ results, summary: { clips: results.length, trueComplete, falseCompletes: falseTotal, scenarios: scenarioTotal } }, null, 1))
  console.log(`wrote ${JSON_OUT}`)
}
